if now - AICCombatUtils.S.LAST_STUCK_TIME >= CONFIG.STUCK_CHECK_INTERVAL then
AICCombatUtils.S.LAST_STUCK_TIME = now
if AICCombatUtils.S.LAST_STUCK_POSITION
